const assert = require('assert');

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const targets = await fetch('http://127.0.0.1:9222/json/list').then((r) => r.json());
  const page = targets.find((target) => target.type === 'page');
  assert(page, 'no page target');

  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();
  const browserLogs = [];

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id) {
      const entry = pending.get(message.id);
      if (!entry) return;
      pending.delete(message.id);
      if (message.error) entry.reject(new Error(JSON.stringify(message.error)));
      else entry.resolve(message.result);
      return;
    }
    if (message.method === 'Runtime.exceptionThrown') {
      browserLogs.push('exception: ' + message.params.exceptionDetails.text);
    }
    if (message.method === 'Log.entryAdded' && message.params.entry.level === 'error') {
      browserLogs.push('log: ' + message.params.entry.text);
    }
  };

  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });

  const evaluate = async (expression) => {
    const result = await send('Runtime.evaluate', {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    if (result.exceptionDetails) {
      throw new Error(result.exceptionDetails.text + ': ' + expression);
    }
    return result.result.value;
  };

  const waitFor = async (expression, timeout = 10000) => {
    const deadline = Date.now() + timeout;
    while (Date.now() < deadline) {
      if (await evaluate(expression)) return;
      await sleep(100);
    }
    throw new Error('timeout waiting for: ' + expression);
  };

  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 1280,
    height: 900,
    deviceScaleFactor: 1,
    mobile: false,
  });
  await send('Page.navigate', { url: 'http://127.0.0.1:5055/#/porsequencia' });
  await waitFor("document.querySelectorAll('.sequencia-linha').length === 6");

  const initial = await evaluate(`(() => ({
    rows: document.querySelectorAll('.sequencia-linha').length,
    form: !!document.querySelector('#form-cadastro-sequencia'),
    expanded: document.querySelector('.sequencia-cadastro-toggle').getAttribute('aria-expanded'),
    cadastroBeforeCatalogo: document.querySelector('.sequencia-cadastro').compareDocumentPosition(document.querySelector('.sequencia-catalogo')) & Node.DOCUMENT_POSITION_FOLLOWING,
    whiteHexes: Array.from(document.querySelectorAll('.sequencia-linha .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length
  }))()`);
  assert.equal(initial.rows, 6);
  assert.equal(initial.form, false);
  assert.equal(initial.expanded, 'false');
  assert(initial.cadastroBeforeCatalogo, 'cadastro should precede catalog');
  assert.equal(initial.whiteHexes, 0);
  console.log('initial', initial);

  await evaluate("document.querySelector('.sequencia-cadastro-toggle').click(); true");
  await waitFor("!!document.querySelector('#form-cadastro-sequencia')");
  await sleep(100);

  const open = await evaluate(`(() => {
    const input = document.querySelector('#nova-sequencia');
    const button = document.querySelector('.sequencia-cadastro-btn');
    const help = document.querySelector('#ajuda-nova-sequencia');
    return {
      expanded: document.querySelector('.sequencia-cadastro-toggle').getAttribute('aria-expanded'),
      focused: document.activeElement === input,
      inputBorder: getComputedStyle(input).borderTopColor,
      inputColor: getComputedStyle(input).color,
      buttonBackground: getComputedStyle(button).backgroundColor,
      buttonBorder: getComputedStyle(button).borderTopColor,
      buttonColor: getComputedStyle(button).color,
      helpColor: getComputedStyle(help).color
    };
  })()`);
  assert.equal(open.expanded, 'true');
  assert(open.focused, 'field should receive focus when opened');
  assert.equal(open.inputBorder, 'rgb(255, 255, 255)');
  assert.equal(open.inputColor, 'rgb(255, 255, 255)');
  assert.equal(open.buttonBorder, 'rgb(255, 255, 255)');
  assert.equal(open.buttonColor, 'rgb(255, 255, 255)');
  console.log('open', open);

  const type = async (value) => {
    await evaluate(`(() => {
      const input = document.querySelector('#nova-sequencia');
      input.value = ${JSON.stringify(value)};
      input.dispatchEvent(new Event('input', { bubbles: true }));
      return true;
    })()`);
  };
  const submit = async () => {
    await evaluate(`(() => {
      document.querySelector('#form-cadastro-sequencia').dispatchEvent(
        new Event('submit', { bubbles: true, cancelable: true })
      );
      return true;
    })()`);
  };

  await evaluate("document.querySelectorAll('.sequencia-linha')[0].click(); true");
  await waitFor("document.querySelectorAll('.sequencia-linha.sequencia-selecionada').length === 1");
  const firstSelection = await evaluate(`(() => ({
    selectedRows: document.querySelectorAll('.sequencia-linha.sequencia-selecionada').length,
    allWhiteHexes: Array.from(document.querySelectorAll('.sequencia-linha .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length,
    firstRowWhiteHexes: Array.from(document.querySelectorAll('.sequencia-linha:first-child .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length,
    secondRowWhiteHexes: Array.from(document.querySelectorAll('.sequencia-linha:nth-child(2) .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length
  }))()`);
  assert.equal(firstSelection.selectedRows, 1);
  assert.equal(firstSelection.firstRowWhiteHexes, 4);
  assert.equal(firstSelection.allWhiteHexes, 4);
  assert.equal(firstSelection.secondRowWhiteHexes, 0);
  console.log('first selection', firstSelection);

  await evaluate("document.querySelectorAll('.sequencia-linha')[1].click(); true");
  await waitFor("document.querySelectorAll('.sequencia-linha.sequencia-selecionada').length === 1 && document.querySelectorAll('.sequencia-linha')[1].classList.contains('sequencia-selecionada')");
  const secondSelection = await evaluate(`(() => ({
    selectedRows: document.querySelectorAll('.sequencia-linha.sequencia-selecionada').length,
    allWhiteHexes: Array.from(document.querySelectorAll('.sequencia-linha .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length,
    firstRowWhiteHexes: Array.from(document.querySelectorAll('.sequencia-linha:first-child .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length,
    secondRowWhiteHexes: Array.from(document.querySelectorAll('.sequencia-linha:nth-child(2) .hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length
  }))()`);
  assert.equal(secondSelection.selectedRows, 1);
  assert.equal(secondSelection.allWhiteHexes, 4);
  assert.equal(secondSelection.firstRowWhiteHexes, 0);
  assert.equal(secondSelection.secondRowWhiteHexes, 4);
  console.log('second selection', secondSelection);

  await type('Dm, G, C');
  await submit();
  await waitFor("document.querySelector('.sequencia-cadastro-sucesso') && document.querySelector('.sequencia-cadastro-sucesso').textContent.trim() === 'Sequência Dm,G,C cadastrada.'");
  await waitFor("document.querySelectorAll('.sequencia-linha').length === 7");

  const created = await evaluate(`(() => {
    const success = document.querySelector('.sequencia-cadastro-sucesso');
    const rows = document.querySelectorAll('.sequencia-linha');
    const selected = document.querySelectorAll('.sequencia-linha.sequencia-selecionada');
    const last = rows[rows.length - 1];
    return {
      message: success.textContent.trim(),
      successBackground: getComputedStyle(success).backgroundColor,
      rows: rows.length,
      selectedRows: selected.length,
      selectedIsLast: selected.length === 1 && selected[0] === last,
      lastChords: Array.from(last.querySelectorAll('.acorde')).map((el) => el.textContent.trim()),
      lastWhiteHexes: Array.from(last.querySelectorAll('.hex')).filter((hex) => getComputedStyle(hex).fill === 'rgb(255, 255, 255)').length,
      inputValue: document.querySelector('#nova-sequencia').value,
      expanded: document.querySelector('.sequencia-cadastro-toggle').getAttribute('aria-expanded')
    };
  })()`);
  assert.equal(created.message, 'Sequência Dm,G,C cadastrada.');
  assert.equal(created.successBackground, 'rgb(55, 36, 120)');
  assert.equal(created.rows, 7);
  assert.equal(created.selectedRows, 1);
  assert(created.selectedIsLast);
  assert.deepEqual(created.lastChords, ['Dm', 'G', 'C']);
  assert.equal(created.lastWhiteHexes, 3);
  assert.equal(created.inputValue, '');
  assert.equal(created.expanded, 'true');
  console.log('created', created);

  await type('Dm, G, C');
  await submit();
  await waitFor("document.querySelector('.sequencia-cadastro-sucesso') && document.querySelector('.sequencia-cadastro-sucesso').textContent.trim() === 'Sequência Dm,G,C já estava cadastrada.'");
  await waitFor("document.querySelectorAll('.sequencia-linha').length === 7");
  const duplicate = await evaluate(`(() => {
    const selected = document.querySelectorAll('.sequencia-linha.sequencia-selecionada');
    const rows = document.querySelectorAll('.sequencia-linha');
    return {
      message: document.querySelector('.sequencia-cadastro-sucesso').textContent.trim(),
      rows: rows.length,
      selectedRows: selected.length,
      selectedIsLast: selected.length === 1 && selected[0] === rows[rows.length - 1],
      inputValue: document.querySelector('#nova-sequencia').value
    };
  })()`);
  assert.equal(duplicate.message, 'Sequência Dm,G,C já estava cadastrada.');
  assert.equal(duplicate.rows, 7);
  assert.equal(duplicate.selectedRows, 1);
  assert(duplicate.selectedIsLast);
  assert.equal(duplicate.inputValue, '');
  console.log('duplicate', duplicate);

  await type('Bm');
  await submit();
  await waitFor("document.querySelector('.sequencia-cadastro-erro') && document.querySelector('.sequencia-cadastro-erro').textContent.trim().length > 0");
  const invalid = await evaluate(`(() => {
    const error = document.querySelector('.sequencia-cadastro-erro');
    return {
      message: error.textContent.trim(),
      errorBackground: getComputedStyle(error).backgroundColor,
      inputValue: document.querySelector('#nova-sequencia').value,
      formPresent: !!document.querySelector('#form-cadastro-sequencia'),
      expanded: document.querySelector('.sequencia-cadastro-toggle').getAttribute('aria-expanded'),
      successPresent: !!document.querySelector('.sequencia-cadastro-sucesso')
    };
  })()`);
  assert.equal(invalid.message, 'informe pelo menos 2 acordes');
  assert.equal(invalid.errorBackground, 'rgb(82, 16, 82)');
  assert.equal(invalid.inputValue, 'Bm');
  assert(invalid.formPresent);
  assert.equal(invalid.expanded, 'true');
  assert.equal(invalid.successPresent, false);
  console.log('invalid', invalid);

  await send('Emulation.setDeviceMetricsOverride', {
    width: 1280,
    height: 600,
    deviceScaleFactor: 1,
    mobile: false,
  });
  await sleep(300);
  const shortViewport = await evaluate(`(() => {
    const panel = document.querySelector('.sequencia-painel');
    const container = panel.querySelector('.viewWindow-panel-container');
    const catalog = document.querySelector('.sequencia-catalogo');
    const cadastro = document.querySelector('.sequencia-cadastro');
    return {
      panelOverflow: getComputedStyle(panel).overflow,
      containerDisplay: getComputedStyle(container).display,
      catalogClientHeight: catalog.clientHeight,
      catalogScrollHeight: catalog.scrollHeight,
      cadastroTop: Math.round(cadastro.getBoundingClientRect().top),
      cadastroVisible: cadastro.getBoundingClientRect().top >= 0 && cadastro.getBoundingClientRect().bottom <= innerHeight
    };
  })()`);
  assert.equal(shortViewport.panelOverflow, 'hidden');
  assert.equal(shortViewport.containerDisplay, 'flex');
  assert(shortViewport.catalogScrollHeight > shortViewport.catalogClientHeight, 'catalog should scroll internally');
  assert(shortViewport.cadastroVisible, 'cadastro should stay visible');
  console.log('short viewport', shortViewport);

  await send('Emulation.setDeviceMetricsOverride', {
    width: 375,
    height: 667,
    deviceScaleFactor: 1,
    mobile: true,
  });
  await sleep(300);
  const mobile = await evaluate(`(() => {
    const panel = document.querySelector('.sequencia-painel');
    const container = panel.querySelector('.viewWindow-panel-container');
    return {
      panelOverflow: getComputedStyle(panel).overflow,
      containerDisplay: getComputedStyle(container).display,
      horizontalOverflow: document.documentElement.scrollWidth > innerWidth + 1,
      cadastroVisible: document.querySelector('.sequencia-cadastro').getBoundingClientRect().top >= 0
    };
  })()`);
  assert.equal(mobile.panelOverflow, 'auto');
  assert.equal(mobile.containerDisplay, 'block');
  assert.equal(mobile.horizontalOverflow, false);
  assert(mobile.cadastroVisible);
  console.log('mobile', mobile);

  await send('Emulation.setDeviceMetricsOverride', {
    width: 1280,
    height: 900,
    deviceScaleFactor: 1,
    mobile: false,
  });
  await sleep(200);
  await evaluate("document.querySelector('.sequencia-cadastro-toggle').click(); true");
  await waitFor("!document.querySelector('#form-cadastro-sequencia')");
  const closed = await evaluate(`(() => ({
    expanded: document.querySelector('.sequencia-cadastro-toggle').getAttribute('aria-expanded'),
    formPresent: !!document.querySelector('#form-cadastro-sequencia')
  }))()`);
  assert.equal(closed.expanded, 'false');
  assert.equal(closed.formPresent, false);
  console.log('closed', closed);

  const severeLogs = browserLogs.filter((line) => !line.includes('favicon'));
  assert.deepEqual(severeLogs, []);
  console.log('browser logs', browserLogs);

  ws.close();
  console.log('UI CHECK OK');
}

main().catch((error) => {
  console.error(error.stack || error);
  process.exit(1);
});

