const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const targets = await fetch('http://127.0.0.1:9222/json/list').then((r) => r.json());
  const page = targets.find((target) => target.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let nextId = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (!message.id) return;
    const entry = pending.get(message.id);
    if (!entry) return;
    pending.delete(message.id);
    if (message.error) entry.reject(new Error(JSON.stringify(message.error)));
    else entry.resolve(message.result);
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async (expression) => {
    const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
    return result.result.value;
  };
  await send('Runtime.enable');
  await send('Page.enable');
  await send('Page.navigate', { url: 'about:blank' });
  await sleep(200);
  await send('Page.navigate', { url: 'http://127.0.0.1:5055/#/porsequencia' });
  for (let i = 0; i < 100; i++) {
    if (await evaluate("document.querySelectorAll('.sequencia-linha').length === 6")) break;
    await sleep(100);
  }
  console.log('rules', await evaluate(`(() => {
    const found = [];
    for (const sheet of document.styleSheets) {
      let rules;
      try { rules = sheet.cssRules; } catch (e) { continue; }
      for (const rule of rules) {
        if (rule.selectorText && rule.selectorText.includes('sequencia-linha')) {
          found.push(rule.cssText);
        }
      }
    }
    return found;
  })()`));
  await evaluate("document.querySelectorAll('.sequencia-linha')[0].click(); true");
  await sleep(500);
  console.log('selected', await evaluate(`(() => {
    const row = document.querySelector('.sequencia-linha.sequencia-selecionada');
    return {
      html: row && row.outerHTML.slice(0, 500),
      cls: row && row.className,
      bg: row && getComputedStyle(row).backgroundColor,
      shadow: row && getComputedStyle(row).boxShadow,
      matched: row && Array.from(document.styleSheets).flatMap((sheet) => {
        try { return Array.from(sheet.cssRules).filter((rule) => rule.selectorText && rule.selectorText.includes('sequencia-selecionada')).map((rule) => rule.cssText); }
        catch (e) { return []; }
      })
    };
  })()`));
  console.log('results before clear', await evaluate("!!document.querySelector('#results')"));
  await evaluate("document.querySelector('#results df-hex').click(); true");
  await sleep(500);
  console.log('after clear', await evaluate(`(() => ({
    results: !!document.querySelector('#results'),
    selectedRows: document.querySelectorAll('.sequencia-linha.sequencia-selecionada').length,
    leftWidth: document.querySelector('.sequencia-painel').getBoundingClientRect().width
  }))()`));
  ws.close();
}
main().catch((error) => { console.error(error.stack || error); process.exit(1); });

